/* Parrlo Translate prototype · app screens C: settings, data & privacy, consent, history, other */
(function(){
const {R,A,SHEETS,ENTER,LEAVE,L,esc,btn,goBtn,I,nav,tg,li_,seg,paras} = PP;
const S = () => PP.S; const T = PP.T; const CP = window.COPY; const lk = PP.lk; const ensureApp = () => PP.ensureApp();

const STYLES = () => [['asSaid',L('Как сказал','Tal cual','As Said'),''],['none',L('Без обработки','Sin retoques','Unprocessed'),L('Слово в слово, как распознано','Palabra por palabra, como se reconoció','Word for word, as recognised')],['literary',L('Литературно','Literario','Literary'),L('Грамотно и вежливо','Correcto y cortés','Correct and polite')],['formal',L('Официально','Formal','Formal'),L('Для врача, банка, госучреждений','Para médico, banco y trámites','For doctors, banks, public offices')]];
const styleName = (k) => (STYLES().find(x=>x[0]===k)||[])[1];
ENTER['app/settings'] = () => ensureApp();
R['app/settings'] = () => { const s=S(), p=s.pair;
  const langName = ({auto:L('Как в iPhone','Como el iPhone','Same as iPhone'),ru:'Русский',es:'Español',en:'English'})[s.ui];
  return `${nav(L('Настройки','Ajustes','Settings'), '#/app/main', L('Назад','Atrás','Back'), `<button class="act" data-go="#/app/main">${esc(L('Готово','Listo','Done'))}</button>`)}<div class="scroll">
  <div class="gh">${esc(L('О вас','Sobre ti','About You'))}</div><div class="grp"><div class="li"><span class="tx"><b>${esc(L('Я','Yo','Me'))}</b></span>${seg([['male',L('Мужчина','Hombre','Man')],['female',L('Женщина','Mujer','Woman')]], s.gender, 'setGender')}</div></div>
  <p class="gf">${esc(L('Для правильных окончаний: «я устал» или «я устала». Пол собеседника — в выборе пары языков.','Para acertar con el género en ruso: «я устал» o «я устала». El género del interlocutor se elige en el par de idiomas.','For correct endings in Russian: «я устал» or «я устала». Partner gender is set in the language pair.'))}</p>
  <div class="gh">${esc(L('Перевод','Traducción','Translation'))}</div><div class="grp">
   ${li_({t:L('Пара языков','Par de idiomas','Language Pair'),a:'pairSheet',val:`${PP.code(p.mine)} ⇄ ${PP.code(p.theirs)}`})}
   ${li_({t:L('Стиль перевода','Estilo','Translation Style'),a:'styleSheet',val:styleName(s.style)})}
   ${li_({t:L('Автоозвучка','Lectura automática','Auto Speak'),s:L('Перевод звучит сам, без кнопки «Произнести»','La traducción suena sola, sin pulsar «Escuchar»','Translation is spoken automatically, no Speak button'),right:tg(s.autoSpeak,'flip','autoSpeak')})}
   ${li_({t:L('Голосовые через «Мой голос»','Audios con «Mi voz»','Voice Messages With My Voice'),s:s.voice.exists?L('«Поделиться → Голосом» звучит вашим голосом.','«Compartir → Con voz» suena con tu voz.','“Share → As Voice” uses your voice.'):L('Голосовые озвучиваются стандартным голосом. Чтобы включить «Мой голос», запишите образец\u00A0— около 30\u00A0секунд.','Los audios se leen con una voz estándar. Para activar «Mi voz», graba una muestra de unos 30\u00A0segundos.','Voice messages use a standard voice. To turn on My Voice, record a sample — about 30\u00A0seconds.'),right:tg(s.shareMyVoice&&s.voice.exists,'shareMyVoiceTg')})}
   ${s.voice.exists?li_({t:L('Мой голос','Mi voz','My Voice'),go:'#/app/myvoice/manage',val:s.voice.on?L('Вкл.','Sí','On'):L('Выкл.','No','Off')}):''}
   ${li_({t:L('Добавлять подпись «Переведено ИИ в Parrlo» к сообщениям в WhatsApp','Añadir la firma «Traducido con IA en Parrlo» a los mensajes de WhatsApp','Add the “AI-Translated With Parrlo” Note to WhatsApp Messages'),s:L('Вы увидите её перед отправкой и сможете убрать','La verás antes de enviar y podrás quitarla','You’ll see it before sending and can remove it'),right:tg(s.waSig,'flip','waSig')})}
   ${li_({t:L('Автоотправка','Envío automático','Auto Send'),s:L('Замолчали — телефон вибрирует и отправляет фразу сам','Al dejar de hablar, el teléfono vibra y envía la frase','Stop talking — the phone vibrates and sends the phrase'),right:tg(s.autoDone,'flip','autoDone')})}
   ${s.autoDone?li_({t:L('Пауза перед отправкой','Pausa antes de enviar','Pause Before Sending'),a:'pauseMenu',val:String(s.pause).replace('.',',')+' '+L('с','s','s')}):''}
   ${li_({t:L('Офлайн-переводчик','Sin\u00A0conexión','Offline Translator'),s:s.offlineModels==='done'?L('Уже в приложении, работает без интернета','Ya viene en la app, funciona sin internet','Built in, works without internet'):L('Быстрее и без интернета. Скачивается по Wi-Fi','Más rápido y sin internet. Se descarga por wifi','Faster and offline. Downloads over Wi-Fi'),go:'#/app/offline',val:s.offlineModels==='done'?L('Встроен','Incluido','Built In'):L('3,9 ГБ','3,9 GB','3.9 GB')})}
  </div>
  <div class="gh">${esc(L('Микрофон','Micrófono','Microphone'))}</div><div class="grp">${li_({t:L('Режим «Шумно»','Modo ruidoso','Noisy Mode'),right:tg(s.noisy,'flip','noisy')})}</div>
  <p class="gf">${esc(L('Для кафе, улицы и музыки: шумоподавление и автоусиление микрофона iPhone. Если звук стал хуже, выключите.','Para cafeterías, calle y música: reducción de ruido y ganancia automática del micrófono del iPhone. Si suena peor, desactívalo.','For cafés, streets and music: iPhone noise reduction and auto gain. If the sound gets worse, turn it off.'))}</p>
  <div class="gh">${esc(L('Приложение','App','App'))}</div><div class="grp">${li_({t:L('Язык','Idioma','Language'),a:'uiLangMenu',val:langName})}</div>
  <div class="gh">${esc(L('Данные','Datos','Data'))}</div><div class="grp">${li_({t:L('История','Historial','History'),go:'#/app/history'})}${li_({t:L('Данные и приватность','Datos y privacidad','Data & Privacy'),go:'#/app/data'})}</div>
  <div class="gh">${esc(L('Помощь','Ayuda','Help'))}</div><div class="grp">${li_({t:L('Написать в поддержку','Escribir a soporte','Contact Support'),s:'hello@parrlo.com',a:'support'})}${li_({t:L('Лицензии','Licencias','Licenses'),go:'#/app/licenses'})}${li_({t:L('Версия','Versión','Version'),s:'2.0 (5c0c39d0) · TestFlight',a:'versionTap',long:'versionLong',noChev:true})}</div>
  </div>`; };
A.flip = (k) => { S()[k]=!S()[k]; };
A.styleSheet = () => { PP.sheet('style'); };
SHEETS.style = () => `<h3>${esc(L('Стиль перевода','Estilo','Translation Style'))}</h3><div class="sb"><div class="grp">${STYLES().map(([k,t,d])=>li_({t, s:d, a:'pickStyle', v:k, right: S().style===k?`<span style="color:var(--green)">${I.check}</span>`:'<span></span>'})).join('')}</div>
  <p class="gf">${esc(L('«Литературно» и «Официально» обрабатывают вашу фразу через облако. Без облака фраза идёт без обработки.','«Literario» y «Formal» procesan tu frase en la nube. Sin la nube, la frase va sin procesar.','“Literary” and “Formal” process your phrase in the cloud. Without the cloud, it goes unprocessed.'))}</p></div><div class="mt">${btn(L('Готово','Listo','Done'),'closeSheet')}</div>`;
A.pickStyle = (v) => { S().style=v; PP.UI.sheet=null; PP.toast(styleName(v)); };
A.shareMyVoiceTg = () => { const s=S(); if (!s.voice.exists){ T.pendingShareVoice=true; T.mvBack='#/app/settings'; PP.go('#/app/myvoice/consent'); return false; } s.shareMyVoice=!s.shareMyVoice; };
A.pauseMenu = () => { PP.menu({head:L('Пауза перед отправкой','Pausa antes de enviar','Pause Before Sending'), items:[1,1.5,2,3].map(n=>({t:String(n).replace('.',',')+' '+L('с','s','s'),a:'pausePick',v:n,r:S().pause==n?'✓':''}))}); };
A.pausePick = (v) => { S().pause=+v; PP.UI.menu=null; };
A.uiLangMenu = () => { PP.menu({head:L('Язык','Idioma','Language'), items:[['auto',L('Как в iPhone','Como el iPhone','Same as iPhone')],['ru','Русский'],['es','Español'],['en','English']].map(([k,t])=>({t,a:'uiPick',v:k,r:S().ui===k?'✓':''}))}); };
A.uiPick = (v) => { S().ui=v; PP.UI.menu=null; };
A.support = () => { PP.sheet('mail'); };
SHEETS.mail = () => `<h3>${esc(L('Новое письмо','Nuevo mensaje','New Message'))}</h3><div class="sb"><div class="grp">${li_({t:L('Кому','Para','To'),val:'hello@parrlo.com'})}${li_({t:L('Тема','Asunto','Subject'),val:'Parrlo Translate 2.0'})}</div><p class="sec sm mt">${esc(L('Откроется приложение Почта с адресом поддержки. В прототипе письмо не отправляется.','Se abrirá Mail con la dirección de soporte. En el prototipo no se envía nada.','Mail opens with the support address. The prototype sends nothing.'))}</p></div>
  <div class="row2 mt">${btn(L('Отмена','Cancelar','Cancel'),'closeSheet',undefined,'ghost')}${btn(L('Отправить','Enviar','Send'),'mailSend')}</div>`;
A.mailSend = () => { PP.UI.sheet=null; PP.toast(L('Письмо готово в Почте','Mensaje listo en Mail','Message ready in Mail')); };
A.versionTap = () => { T.vt=(T.vt||0)+1; if (T.vt>=5){ T.vt=0; PP.go('#/app/diagnostics'); return false; } PP.toast('Parrlo Translate 2.0 · 5c0c39d0'); };
A.versionLong = () => { PP.go('#/app/diagnostics'); return false; };

/* Data & privacy */
const scopeName = (sc) => sc==='voiceText'?L('Голос и текст','Voz y texto','Voice and text'):sc==='text'?L('Только текст','Solo texto','Text only'):L('Выключено','Desactivada','Off');
ENTER['app/data'] = () => ensureApp();
R['app/data'] = () => { const s=S();
  const days = ({0:L('Всегда','Siempre','Always'),7:L('7 дней','7 días','7 days'),30:L('30 дней','30 días','30 days'),90:L('90 дней','90 días','90 days')})[s.days];
  return `${nav(L('Данные и приватность','Datos y privacidad','Data & Privacy'),'#/app/settings',L('Настройки','Ajustes','Settings'))}<div class="scroll">
  <div class="gh">${esc(lk('toggleRow'))}</div><div class="grp">${li_({t:lk('toggleRow'),go:'#/app/cloud-scope',val:scopeName(s.scope)})}${li_({t:lk('toggleVoiceRow'),go:'#/app/cloud-scope',val:s.scope==='voiceText'?L('Вкл.','Sí','On'):L('Выкл.','No','Off')})}${s.scope!=='none'?li_({t:lk('revokeRow'),a:'revokeAsk',dng:true,noChev:true}):''}</div>
  <div class="grp" style="margin-top:12px">${li_({t:lk('diagnosticsRow'),right:tg(s.diag,'flip','diag')})}</div><p class="gf">${esc(lk('diagnosticsFooter'))}</p>
  <div class="gh">${esc(L('История','Historial','History'))}</div><div class="grp">${li_({t:L('Хранить историю','Guardar historial','Keep History'),right:tg(s.keepHistory,'flip','keepHistory')})}${s.keepHistory?li_({t:L('Срок хранения','Conservar','Keep For'),a:'daysMenu',val:days}):''}</div>
  <p class="gf">${esc(L('История хранится только на этом телефоне.','El historial se guarda solo en este teléfono.','History is stored only on this phone.'))}</p>
  <div class="gh">${esc(L('Отметки «Неточно»','Marcas «Inexacto»','“Inaccurate” Marks'))}</div><p class="gf">${esc(L('Когда вы отмечаете перевод как неточный, фраза и перевод отправляются нам, чтобы улучшить Parrlo. Без звука.','Cuando marcas una traducción como inexacta, la frase y la traducción se nos envían para mejorar Parrlo. Sin audio.','When you mark a translation as inaccurate, the phrase and translation are sent to us to improve Parrlo. No audio.'))}</p>
  <div class="gh">${esc(L('Клавиатура','Teclado','Keyboard'))}</div><div class="grp">${li_({t:PP.C(CP.KB['keyboard.full.title']),go:'#/app/kb-access'})}</div>
  <div class="grp" style="margin-top:20px">${li_({t:L('Очистить историю','Borrar historial','Clear History'),a:'clearHistAsk',dng:true,noChev:true})}${li_({t:L('Удалить все данные','Eliminar todos los datos','Delete All Data'),a:'deleteAllAsk',dng:true,noChev:true})}</div>
  <p class="gf">${esc(L('Parrlo не сохраняет запись вашего голоса на своих серверах.','Parrlo no guarda la grabación de tu voz en sus servidores.','Parrlo doesn’t keep recordings of your voice on its servers.'))}</p></div>`; };
A.daysMenu = () => { PP.menu({head:L('Срок хранения','Conservar','Keep For'), items:[[7,L('7 дней','7 días','7 days')],[30,L('30 дней','30 días','30 days')],[90,L('90 дней','90 días','90 days')],[0,L('Всегда','Siempre','Always')]].map(([k,t])=>({t,a:'daysPick',v:k,r:S().days==k?'✓':''}))}); };
A.daysPick = (v) => { S().days=+v; PP.UI.menu=null; };
A.clearHistAsk = () => { PP.dialog({title:L('Очистить историю?','¿Borrar el historial?','Clear History?'), msg:L('Все сохранённые разговоры на этом телефоне будут удалены.','Se eliminarán todas las conversaciones guardadas en este teléfono.','All saved conversations on this phone will be deleted.'), buttons:[{t:L('Очистить историю','Borrar historial','Clear History'),a:'clearHist',cls:'dng'},{t:L('Отмена','Cancelar','Cancel'),a:'noop'}]}); };
A.clearHist = () => { S().history=[]; PP.toast(L('История очищена','Historial borrado','History cleared')); };
A.deleteAllAsk = () => { PP.dialog({title:L('Удалить все данные?','¿Eliminar todos los datos?','Delete All Data?'), msg:L('История, журнал реплик и жалобы на этом телефоне будут удалены. Голос на сервере тоже.','Se eliminarán el historial, el registro de frases y las quejas de este teléfono. También la voz del servidor.','History, the phrase log and reports on this phone will be deleted. The voice on the server too.'), buttons:[{t:L('Удалить все данные','Eliminar todos los datos','Delete All Data'),a:'deleteAll',cls:'dng'},{t:L('Отмена','Cancelar','Cancel'),a:'noop'}]}); };
A.deleteAll = () => { const s=S(); s.history=[]; s.voice={exists:false,on:false,used:0,consentVer:null}; s.shareMyVoice=false;
  PP.dialog({title:L('Данные удалены','Datos eliminados','Data Deleted'), msg:L('История, журнал реплик и жалобы на этом телефоне удалены.','Se eliminaron el historial, el registro de frases y las quejas de este teléfono.','History, the phrase log and reports on this phone were deleted.'), buttons:[{t:L('Понятно','Entendido','OK'),a:'noop',cls:'pri'}]}); };
A.revokeAsk = () => { PP.dialog({title:lk('revokeRow')+'?', msg:L('Если выключить, голос и текст не будут отправляться на сервер, а перевод будет озвучиваться голосом iPhone. Офлайн-перевод (по подписке) продолжит работать на телефоне. Включить можно в любой момент.','Si la desactivas, ni tu voz ni tu texto se enviarán al servidor y la traducción se leerá con la voz del iPhone. La traducción sin conexión (con suscripción) seguirá funcionando en el teléfono. Puedes volver a activarla cuando quieras.','If you turn it off, your voice and text won’t be sent to the server and translations will use the iPhone voice. Offline translation (with a subscription) keeps working on the phone. You can turn it back on at any time.'), buttons:[{t:L('Выключить','Desactivar','Turn Off'),a:'revoke',cls:'dng'},{t:L('Отмена','Cancelar','Cancel'),a:'noop'}]}); };
A.revoke = () => { S().scope='none'; S().kb.everConnected=true; PP.sheet('revoked'); };
SHEETS.revoked = () => `<h3>${esc(lk('revokedTitle'))}</h3><div class="sb legal"><p>${esc(L('Голос и текст больше не отправляются на сервер. Перевод озвучивается голосом iPhone, а офлайн-перевод (по подписке) продолжает работать на телефоне.','Tu voz y tu texto ya no se envían al servidor. La traducción se lee con la voz del iPhone y la traducción sin conexión (con suscripción) sigue funcionando en el teléfono.','Your voice and text are no longer sent to the server. Translations use the iPhone voice, and offline translation (with a subscription) keeps working on the phone.'))}</p><p>${esc(L('Уже обработанное это не отменяет: сервис распознавания речи, сторонний ИИ-сервис и сервис синтеза речи могут временно хранить ранее отправленные данные. Запись вашего голоса мы на своих серверах не сохраняем.','Esto no anula lo ya procesado: el servicio de reconocimiento de voz, el servicio de IA de terceros y el de síntesis de voz pueden conservar temporalmente los datos enviados antes. No guardamos la grabación de tu voz en nuestros servidores.','This doesn’t undo what was already processed: the speech-recognition service, the third-party AI service and the speech-synthesis service may temporarily keep data sent earlier. We don’t keep voice recordings on our servers.'))}</p><p>${esc(L('История разговоров остаётся на телефоне; удалить её можно в этом же разделе.','El historial de conversaciones se queda en el teléfono; puedes borrarlo en esta misma sección.','Conversation history stays on the phone; you can delete it in this section.'))}</p></div><div class="mt">${btn(lk('revokedOK'),'closeSheet')}</div>`;
ENTER['app/cloud-scope'] = () => ensureApp();
R['app/cloud-scope'] = () => { const s=S(); const ch = (k) => `<button class="choice ${s.scope===k?'on':''}" ${PP.attr('setScope',k)}><span class="big">${esc(scopeName(k))}</span></button>`;
  return `${nav(lk('toggleRow'),'#/app/data',L('Данные','Datos','Data'))}<div class="scroll legal">${ch('voiceText')}${ch('text')}${ch('none')}<div class="gh">${esc(lk('toggleHowLink'))}</div>${paras(PP.C(CP.CLOUD.voiceText))}<p><button class="lnk" ${PP.attr('legal','privacy')}>${esc(lk('emptyMore'))}</button></p></div>`; };
A.setScope = (v) => { if (v==='none' && S().scope!=='none'){ A.revokeAsk(); return; } S().scope=v; S().kb.everConnected=true; PP.toast(scopeName(v)); };
ENTER['app/consent'] = () => { if (S().age===null) S().age='ok'; S().intro=true; };
R['app/consent'] = () => `${nav('', T.consentBack||'#/app/main', L('Назад','Atrás','Back'))}${PP.consentBody()}<div class="foot">${btn(lk('allow'),'consentAllow','app')}${btn(lk('notNow'),'consentNotNow','app','ghost')}</div>`;
function kbAccessBody(){ const k=(x)=>PP.C(CP.KB['keyboard.full.'+x]);
  return `<div class="scroll legal"><h1 class="t" style="font-size:26px">${esc(k('title'))}</h1><p>${esc(k('intro'))}</p>${[1,2,3,4,5,6].map(i=>`<p>• ${esc(k('p'+i))}</p>`).join('')}<p><b>${esc(k('how'))}</b></p><p class="sec"><button class="lnk" ${PP.attr('legal','privacy')}>${esc(k('link'))}</button></p></div>`; }
PP.kbAccessBody = kbAccessBody;
ENTER['app/kb-access'] = () => ensureApp();
R['app/kb-access'] = () => `${nav('', '#/app/data', L('Данные и приватность','Datos y privacidad','Data & Privacy'))}${kbAccessBody()}<div class="foot">${goBtn(PP.C(CP.KB['keyboard.full.button']),'#/kb/ios/parrlo')}</div>`;

/* History */
const dayName = (d) => { const n=new Date(); const x=new Date(d); const diff=Math.round((new Date(n.toDateString())-new Date(x.toDateString()))/864e5); return diff===0?L('Сегодня','Hoy','Today'):diff===1?L('Вчера','Ayer','Yesterday'):x.toLocaleDateString(PP.lang()); };
const hhmm = (d) => { const x=new Date(d); return x.getHours()+':'+String(x.getMinutes()).padStart(2,'0'); };
ENTER['app/history'] = () => { ensureApp(); T.histQ=''; };
R['app/history'] = () => { const s=S(); const q=(T.histQ||'').toLowerCase();
  const list = s.history.filter(c=>!q || c.items.some(i=>(i[1]+' '+i[2]).toLowerCase().includes(q)));
  const groups = {}; list.forEach(c=>{ const g=dayName(c.date); (groups[g]=groups[g]||[]).push(c); });
  return `${nav(L('История','Historial','History'),'#/app/main',L('Назад','Atrás','Back'))}<div class="scroll">
  ${s.history.length?`<input id="histq" data-input="histQ" value="${esc(T.histQ||'')}" placeholder="${esc(L('Поиск','Buscar','Search'))}" style="width:100%;padding:10px 14px;border-radius:12px;border:1px solid var(--line);background:var(--surface);margin:4px 0 6px;outline:none">`:''}
  ${s.history.length===0?`<div class="empty" style="min-height:420px"><h2 class="t" style="color:var(--text)">${esc(L('Здесь появятся ваши разговоры','Aquí aparecerán tus conversaciones','Your Conversations Will Appear Here'))}</h2><p>${esc(L('Нажмите «Завершить разговор» в конце — он сохранится на этом телефоне.','Pulsa «Finalizar conversación» al acabar y la conversación se guardará en este teléfono.','Tap “End Conversation” at the end — it will be saved on this phone.'))}</p>${S().sharedOnce?'':`<div class="hintcard" style="margin:12px 0 0">${esc(PP.C(CP.SL.l5Hint))}</div>`}</div>`:
   Object.entries(groups).map(([g,cs])=>`<div class="gh">${esc(g)}</div><div class="grp">${cs.map(c=>li_({t:c.items[0][1], s:`${hhmm(c.date)} · ${PP.code(c.pair[0])} ⇄ ${PP.code(c.pair[1])} · ${c.items.length}`, go:'#/app/history/'+c.id})).join('')}</div>`).join('') || `<p class="sec center mt">${esc(L('Ничего не найдено','Sin resultados','No results'))}</p>`}
  </div>`; };
R['app/history/:id'] = (id) => { ensureApp(); const c=S().history.find(x=>x.id===id);
  if (!c) return `${nav('', '#/app/history', L('История','Historial','History'))}<div class="empty">${esc(L('Разговор удалён','Conversación eliminada','Conversation deleted'))}</div>`;
  return `${nav(dayName(c.date)+', '+hhmm(c.date),'#/app/history',L('История','Historial','History'))}<div class="feed">${c.items.map(([side,src,out],i)=>`<div class="turn ${side}"><span class="src">${esc(src)}</span><button class="bub ${T.playing==='h'+i?'playing':''}" ${PP.attr('histSpeak',i+'|'+c.id)}>${esc(out)}</button></div>`).join('')}</div>
  <div class="foot"><div class="row2">${btn(L('Скопировать всё','Copiar todo','Copy All'),'histCopy',c.id,'sec')}${btn(L('Удалить','Eliminar','Delete'),'histDelAsk',c.id,'dng')}</div></div>`; };
A.histSpeak = (v) => { const [i,id]=v.split('|'); const c=S().history.find(x=>x.id===id); const it=c.items[+i]; const lang = it[0]==='me'?c.pair[1]:c.pair[0]; if (T.playing==='h'+i){ PP.stopSpeak(); return; } PP.speak(it[2], lang, 'h'+i); return false; };
A.histCopy = (id) => { const c=S().history.find(x=>x.id===id); PP.copy(c.items.map(i=>i[1]+'\n'+i[2]).join('\n\n')); PP.toast(L('Скопировано','Copiado','Copied')); };
A.histDelAsk = (id) => { PP.dialog({title:L('Удалить разговор?','¿Eliminar la conversación?','Delete Conversation?'), buttons:[{t:L('Удалить','Eliminar','Delete'),a:'histDel',v:id,cls:'dng'},{t:L('Отмена','Cancelar','Cancel'),a:'noop'}]}); };
A.histDel = (id) => { const s=S(); s.history=s.history.filter(x=>x.id!==id); PP.go('#/app/history'); return false; };

/* Other screens */
ENTER['app/offline'] = () => ensureApp();
R['app/offline'] = () => { const s=S(); const dl=T.dl;
  const status = s.offlineModels==='done'?L('Скачано','Descargado','Downloaded'):dl!=null?L(`Скачиваем модели · ${dl}%`,`Descargando modelos · ${dl}%`,`Downloading models · ${dl}%`):L('Модели ещё не скачаны — пока облако','Modelos aún no descargados: de momento la nube','Models not downloaded yet — using the cloud for now');
  return `${nav(L('Офлайн-переводчик','Sin conexión','Offline Translator'),'#/app/settings',L('Настройки','Ajustes','Settings'))}<div class="scroll"><div class="card"><b>${esc(status)}</b>${dl!=null&&s.offlineModels!=='done'?`<div class="prog"><i style="width:${dl}%"></i></div>`:''}<p class="sec sm" style="margin-top:8px">${esc(L('Быстрее и без интернета. Скачивается по Wi-Fi','Más rápido y sin internet. Se descarga por wifi','Faster and offline. Downloads over Wi-Fi'))}</p></div>
  <p class="sec sm">${esc(L('Когда сети нет, речь распознаётся и переводится на телефоне. Модели занимают около 3,9 ГБ.','Sin red, la voz se reconoce y se traduce en el teléfono. Los modelos ocupan unos 3,9 GB.','Without a network, speech is recognised and translated on the phone. Models take about 3.9 GB.'))}</p></div>
  <div class="foot">${s.offlineModels==='done'?btn(L('Удалить модели','Eliminar modelos','Delete Models'),'modelsDel',undefined,'dng'):btn(L('Скачать модели · 3,9 ГБ · Wi-Fi','Descargar los modelos · 3,9 GB · Wi-Fi','Download Models · 3.9 GB · Wi-Fi'),'modelsDl',undefined,'pri',dl!=null?'disabled':'')}</div>`; };
A.modelsDl = () => { T.dl=0; const iv=setInterval(()=>{ T.dl+=10; if (T.dl>=100){ clearInterval(iv); S().offlineModels='done'; T.dl=null; PP.save(); } if (PP.route()==='app/offline') PP.render(); }, 250); };
A.modelsDel = () => { S().offlineModels='none'; PP.toast(L('Модели удалены','Modelos eliminados','Models deleted')); };
R['app/licenses'] = () => `${nav(L('Лицензии','Licencias','Licenses'),'#/app/settings',L('Настройки','Ajustes','Settings'))}<div class="scroll"><div class="grp">${[['Inter','SIL Open Font License 1.1'],['Nunito','SIL Open Font License 1.1'],[L('Модель распознавания речи на телефоне','Modelo de reconocimiento de voz en el teléfono','On-Device Speech Model'),'MIT License']].map(([a,b])=>li_({t:a,s:b})).join('')}</div><p class="gf">${esc(L('Полный список — в приложении.','La lista completa está en la app.','The full list is in the app.'))}</p></div>`;
R['app/diagnostics'] = () => `${nav(L('Диагностика','Diagnóstico','Diagnostics'),'#/app/settings',L('Настройки','Ajustes','Settings'))}<div class="scroll"><div class="grp">${li_({t:L('ИД установки','ID de instalación','Install ID'),s:'demo-7f3a-0000-proto',a:'copyText',v:'demo-7f3a-0000-proto',noChev:true,val:L('Скопировать','Copiar','Copy')})}${li_({t:L('Сборка','Build','Build'),s:'Parrlo Translate · 5c0c39d0'})}${li_({t:L('Перевод в облаке','Traducción en la nube','Cloud Translation'),s:scopeName(S().scope)})}${li_({t:L('Сеть','Red','Network'),s:S().demo.offline?L('Нет интернета','Sin internet','No internet'):'OK'})}</div><p class="gf">${esc(L('Скрытый экран: долгое нажатие на «Версия». В сборке App Store недоступен.','Pantalla oculta: mantén pulsado «Versión». No disponible en la versión de App Store.','Hidden screen: long-press Version. Not available in the App Store build.'))}</p></div>`;
})();
